use super::*;

/// The cue one coordination event should sound, or `None` when the event is not voiced.
///
/// A landing/merge is `success`, a failure is `error`, a worker pausing for the user (`bsc-wait`) is
/// `notify`. **Everything else is deliberately SILENT** — `closed`, `ask`, `assign`, `fork`, `brief`
/// and the rest are not user-facing completions or pauses, and a notifier that voiced every line
/// would be noise the user turns off, which is the same as having none.
pub fn coord_event_cue(ev: &CoordEvent) -> Option<&'static str> {
    match ev {
        CoordEvent::Landed { .. } | CoordEvent::Merged { .. } => Some("success"),
        CoordEvent::Failed { .. } => Some("error"),
        CoordEvent::Waiting { .. } => Some("notify"),
        _ => None,
    }
}
